package net.jamesjennison.spoolio.core

enum class WritePhase { DRAFT, AWAITING_TAG, INSPECTING, NEEDS_OVERWRITE_CONSENT, WRITING, VERIFYING, VERIFIED, CANCELLED, REJECTED, FAILED_BEFORE_WRITE, WRITE_OUTCOME_UNKNOWN, UNRESOLVED_ARCHIVED }
class TagRecord(val tnf:Int,val mime:String,payload:ByteArray){private val frozen=payload.copyOf();val payload:ByteArray get()=frozen.copyOf();internal fun payloadUnsafe()=frozen}
class TagSnapshot(uid:ByteArray,val writable:Boolean,val maxNdefSize:Int,records:List<TagRecord>){private val frozenUid=uid.copyOf();val uid:ByteArray get()=frozenUid.copyOf();val records=records.map{TagRecord(it.tnf,it.mime,it.payload)};internal fun uidUnsafe()=frozenUid}
data class WriteState(val phase: WritePhase, val intent: OpenSpoolIntent? = null, private val frozenUid: ByteArray? = null, val detail: String = "") { val uid:ByteArray? get()=frozenUid?.copyOf(); internal fun uidUnsafe()=frozenUid }

class WriteStateMachine {
    var state = WriteState(WritePhase.DRAFT); private set
    private var approvedExistingFingerprint:ByteArray?=null
    private var expectedPayload:ByteArray?=null
    fun arm(intent: OpenSpoolIntent) { require(state.phase in setOf(WritePhase.DRAFT,WritePhase.CANCELLED,WritePhase.REJECTED,WritePhase.FAILED_BEFORE_WRITE,WritePhase.UNRESOLVED_ARCHIVED));approvedExistingFingerprint=null;pendingConsentFingerprint=null;expectedPayload=null;state=WriteState(WritePhase.AWAITING_TAG,intent,detail="Tap an NTAG215") }
    fun inspected(tag: TagSnapshot, ndefMessageSize: Int) {
        val intent=state.intent ?: error("No intent"); require(state.phase==WritePhase.AWAITING_TAG || state.phase==WritePhase.INSPECTING || state.phase==WritePhase.NEEDS_OVERWRITE_CONSENT)
        state=state.copy(phase=WritePhase.INSPECTING,frozenUid=tag.uid,detail="Inspecting writable capacity")
        if(!tag.writable) { state=state.copy(phase=WritePhase.REJECTED,detail="Tag is read-only"); return }
        if(ndefMessageSize>tag.maxNdefSize) { state=state.copy(phase=WritePhase.REJECTED,detail="Message needs $ndefMessageSize bytes; tag reports ${tag.maxNdefSize}"); return }
        val fingerprint=tagFingerprint(tag)
        if(tag.records.isNotEmpty()&&(approvedExistingFingerprint==null||!fingerprint.contentEquals(approvedExistingFingerprint))) { approvedExistingFingerprint=null;pendingConsentFingerprint=fingerprint;state=state.copy(phase=WritePhase.NEEDS_OVERWRITE_CONSENT,detail="Existing content requires approval bound to this tag and content");return }
        pendingConsentFingerprint=null
        expectedPayload=intent.payload
        state=state.copy(phase=WritePhase.WRITING,detail="Keep tag in place")
    }
    fun approveOverwrite(){require(state.phase==WritePhase.NEEDS_OVERWRITE_CONSENT);approvedExistingFingerprint=pendingConsentFingerprint?.copyOf()?:error("No inspected content");state=state.copy(phase=WritePhase.AWAITING_TAG,detail="Approval recorded. Re-tap the same unchanged tag.")}
    fun writeReturned() { require(state.phase==WritePhase.WRITING); state=state.copy(phase=WritePhase.VERIFYING,detail="Remove and re-present only if asked") }
    fun writeInterrupted(reason:String) { require(state.phase==WritePhase.WRITING||state.phase==WritePhase.VERIFYING); state=state.copy(phase=WritePhase.WRITE_OUTCOME_UNKNOWN,detail="$reason. Re-tap for read-only reconciliation; no rewrite will occur.") }
    fun writeFailedBeforeCall(reason:String) { require(state.phase==WritePhase.WRITING); state=state.copy(phase=WritePhase.FAILED_BEFORE_WRITE,detail=reason) }
    fun rejectBeforeWrite(reason:String){require(state.phase in setOf(WritePhase.AWAITING_TAG,WritePhase.INSPECTING,WritePhase.NEEDS_OVERWRITE_CONSENT));state=state.copy(phase=WritePhase.REJECTED,detail=reason)}
    fun reconciled(tag: TagSnapshot) {
        require(state.phase==WritePhase.VERIFYING||state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN)
        val intendedUid=state.uid
        if(intendedUid==null||!intendedUid.contentEquals(tag.uid)) { state=state.copy(phase=WritePhase.WRITE_OUTCOME_UNKNOWN,detail="A different tag was presented"); return }
        val intent=state.intent
        val record=tag.records.singleOrNull()
        val matches=record!=null&&record.tnf==2&&record.mime==OpenSpoolCodec.MIME&&(if(intent!=null)OpenSpoolCodec.semanticallyMatches(intent,record.payloadUnsafe())else expectedPayload?.let{expected->semanticPayloadsMatch(expected,record.payloadUnsafe())}==true)
        state=if(matches) state.copy(phase=WritePhase.VERIFIED,detail="Fresh one-record NDEF message matches the frozen write intent") else state.copy(phase=WritePhase.WRITE_OUTCOME_UNKNOWN,detail=if(tag.records.isEmpty()) "No NDEF message returned by this read; outcome remains unknown; no automatic rewrite" else "Fresh NDEF message does not match; no automatic rewrite")
    }
    fun restoreUnknown(uid:ByteArray,payload:ByteArray){require(state.phase==WritePhase.DRAFT);expectedPayload=payload.copyOf();state=WriteState(WritePhase.WRITE_OUTCOME_UNKNOWN,null,uid.copyOf(),"A prior write may have reached the tag. Re-tap for read-only reconciliation.")}
    fun unknownReadFailed(reason:String){require(state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN);state=state.copy(detail="$reason. The outcome remains unknown; re-tap the same tag for read-only reconciliation.")}
    fun archiveUnknown(){require(state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN);state=WriteState(WritePhase.UNRESOLVED_ARCHIVED,detail="Unresolved write archived without claiming cancellation or verification")}
    fun cancel() { if(state.phase==WritePhase.WRITING||state.phase==WritePhase.VERIFYING||state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN) { if(state.phase!=WritePhase.WRITE_OUTCOME_UNKNOWN)writeInterrupted("Operation interrupted") } else state=state.copy(phase=WritePhase.CANCELLED,detail="Cancelled before writing") }

    private fun semanticPayloadsMatch(a:ByteArray,b:ByteArray):Boolean{val x=OpenSpoolCodec.decode(a) as? DecodeResult.Supported?:return false;val y=OpenSpoolCodec.decode(b) as? DecodeResult.Supported?:return false;return x.values==y.values}
    private fun tagFingerprint(tag:TagSnapshot)=tagFingerprint(tag.uidUnsafe(),tag.records)
    private fun tagFingerprint(uid:ByteArray,records:List<TagRecord>):ByteArray {val digest=java.security.MessageDigest.getInstance("SHA-256");fun sized(bytes:ByteArray){digest.update(java.nio.ByteBuffer.allocate(4).putInt(bytes.size).array());digest.update(bytes)};sized(uid);digest.update(java.nio.ByteBuffer.allocate(4).putInt(records.size).array());records.forEach{digest.update(java.nio.ByteBuffer.allocate(4).putInt(it.tnf).array());sized(it.mime.encodeToByteArray());sized(it.payloadUnsafe())};return digest.digest()}
    private var pendingConsentFingerprint:ByteArray?=null
}

